const { PDFDocument } = require('pdf-lib');

// 1. Obtenemos los bytes puros (Buffer) para no saturar la memoria
const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const logoBuffer = await this.helpers.getBinaryDataBuffer(0, 'marca_agua');

// 2. Cargamos el PDF y el Logo en la librería
const pdfDoc = await PDFDocument.load(pdfBuffer);
const logoImage = await pdfDoc.embedPng(logoBuffer);

// 3. Recorremos todas las páginas
const pages = pdfDoc.getPages();

for (const page of pages) {
  // Obtenemos el tamaño real de la hoja actual (ej: A4 es 595x842)
  const { width, height } = page.getSize();

  // -- MAGIA MATEMÁTICA --
  // Queremos que el logo ocupe el 60% del ancho de la página
  const anchoDeseado = width * 0.90; 

  // Calculamos por cuánto hay que multiplicar el logo original para llegar a ese ancho
  const factorDeEscala = anchoDeseado / logoImage.width;

  // Aplicamos ese factor. Esto achica el ancho y el alto proporcionalmente para que no se deforme.
  const logoDims = logoImage.scale(factorDeEscala); 
  // ------------------------

  // Dibujamos el logo calculando el centro exacto de la hoja
  page.drawImage(logoImage, {
    x: width / 2 - logoDims.width / 2,
    y: height / 2 - logoDims.height / 2,
    width: logoDims.width,
    height: logoDims.height
  });
}

// 4. Guardamos los cambios
const pdfBytes = await pdfDoc.save();

// 5. Devolvemos el archivo impecable para n8n
$input.item.binary = $input.item.binary || {};
$input.item.binary.Imagen_completa = await this.helpers.prepareBinaryData(Buffer.from(pdfBytes), 'parcial_marcado.pdf', 'application/pdf');
return $input.item;

